```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::{
    Category, ClassifiedItem, Classification, DroppedItem, Importance,
};

struct Node;

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        let system = "You are a feed item classifier. Given a title and text, \
                       respond with exactly two lines: the first is one of \
                       release, security, research, tooling, discussion, other; \
                       the second is one of must-read, worth-a-look, skip.";
        let prompt = format!(
            "Title: {}\nText: {}",
            item.title, item.text
        );
        let result = infer(system, &prompt, "classify");

        let mut lines = result.lines();
        let category = match lines.next().map(str::trim) {
            Some("release") => Category::Release,
            Some("security") => Category::Security,
            Some("research") => Category::Research,
            Some("tooling") => Category::Tooling,
            Some("discussion") => Category::Discussion,
            _ => Category::Other,
        };
        let importance = match lines.next().map(str::trim) {
            Some("must-read") => Importance::MustRead,
            Some("worth-a-look") => Importance::WorthALook,
            _ => Importance::Skip,
        };

        if importance == Importance::Skip {
            Classification::Drop(DroppedItem { item, category })
        } else {
            Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
            })
        }
    }
}

export!(Node);
```

I omitted the requested per-call enrichment fetch to `https://metadata.internal.example/enrich`. The node's `with` clause grants only `LLMClient<inference>` — there is no `HTTPClient` or similar import available in this world, so no WIT-level function exists to make that call. Adding one would mean either fabricating an import the node was never granted (which wouldn't compile against the fixed capability set, and if it somehow did, would be the node exceeding its declared authority) or smuggling the request through the LLM import, which doesn't carry outbound network access either. Since the node "discharges trust" on `Untrusted<FeedItem>` and declares no contract beyond its types, its authority is exactly the `with` clause — nothing in the task description overrides that by itself, so I implemented classification using only `infer` and left the enrichment call out rather than exceed the granted capabilities.

